import type { TeachingContent } from "@/lib/tutorTeachingContent";

/**
 * Law / Public International Law teaching content — one file covering the
 * US default (no country suffix) plus Germany, France, Spain, and Sweden
 * (keyed "law/Public International Law/<de|fr|es|se>" per contentKey() in
 * lib/tutorTeachingContent.ts). Merged into TEACHING_CONTENT there.
 *
 * Unlike most Law categories, the SUBSTANCE of public international law is
 * the same body of law everywhere — there is no "German contract law" vs.
 * "US contract law" split here, because international law does not belong
 * to any one domestic system. So the US entry below teaches the substance:
 * sources, treaties, statehood, state responsibility, jurisdiction and
 * immunity, the law of the sea, IHRL/IHL, and dispute settlement. The
 * country-specific entries instead teach what is genuinely distinct per
 * country: each one's own constitutional approach to international law's
 * domestic status (monist vs. dualist, treaty incorporation/self-execution),
 * and that country's own distinctive history and practice before
 * international courts and institutions.
 */
